34	// edgeSet 把道路列表转成规范集合，便于比较。
35	func edgeSet(edges []Edge) map[Edge]struct{} {
36		set := make(map[Edge]struct{}, len(edges))
37		for _, e := range edges {
38			set[canonicalEdge(e)] = struct{}{}
39		}
40		return set
41	}
42	
43	// assertMapShape 检查生成地图的通用性质：道路数量、无重复、规范方向、
44	// 包含必有道路、避开禁用道路、全图连通。
45	func assertMapShape(t *testing.T, st State, req GenerateRequest) {
46		t.Helper()
47		edges := st.Rules.Edges
48		if len(edges) != req.RoadCount {
49			t.Fatalf("道路数量应为 %d，得到 %d: %v", req.RoadCount, len(edges), edges)
50		}
51		set := make(map[Edge]struct{}, len(edges))
52		for _, e := range edges {
53			if e.From >= e.To {
54				t.Fatalf("道路方向不规范: %+v", e)
55			}
56			if _, dup := set[e]; dup {
57				t.Fatalf("道路重复: %+v", e)
58			}
59			set[e] = struct{}{}
60		}
61		for _, r := range req.Required {
62			if _, ok := set[canonicalEdge(r)]; !ok {
63				t.Fatalf("必有道路 %+v 不在地图中: %v", r, edges)
64			}
65		}
66		for _, b := range req.Banned {
67			if _, ok := set[canonicalEdge(b)]; ok {
68				t.Fatalf("禁用道路 %+v 出现在地图中: %v", b, edges)
69			}
70		}
71		// 连通性：从任一地点出发应能到达全部地点。
72		adj := make(map[string][]string)
73		for _, e := range edges {
74			adj[e.From] = append(adj[e.From], e.To)
75			adj[e.To] = append(adj[e.To], e.From)
76		}
77		seen := map[string]struct{}{st.Rules.Locations[0]: {}}
78		queue := []string{st.Rules.Locations[0]}
79		for len(queue) > 0 {
80			cur := queue[0]
81			queue = queue[1:]
82			for _, nb := range adj[cur] {
83				if _, ok := seen[nb]; !ok {
84					seen[nb] = struct{}{}
85					queue = append(queue, nb)
86				}
87			}
88		}
89		if len(seen) != len(st.Rules.Locations) {
90			t.Fatalf("地图不连通: 从 %q 只能到达 %d/%d 个地点",
91				st.Rules.Locations[0], len(seen), len(st.Rules.Locations))
92		}
93	}
