119	func TestGenerateDeterministic(t *testing.T) {
120		req := baseGenerateRequest()
121		first := generateWorld(t, req).Snapshot()
122	
123		// 重复调用结果一致。
124		again := generateWorld(t, req).Snapshot()
125		if !reflect.DeepEqual(first.Rules, again.Rules) {
126			t.Fatalf("重复生成结果不同:\n%v\n%v", first.Rules.Edges, again.Rules.Edges)
127		}
128	
129		// 先生成其他世界不影响结果。
130		other := req
131		other.Seed = 999
132		_ = generateWorld(t, other)
133		third := generateWorld(t, req).Snapshot()
134		if !reflect.DeepEqual(first.Rules, third.Rules) {
135			t.Fatal("生成其他世界后，同种子同约束的结果发生变化")
136		}
137	
138		// 输入次序、重复道路与正反写法不影响结果。
139		shuffled := req
140		shuffled.Locations = []string{"dock", "cave", "yard", "hall"}
141		shuffled.Required = []Edge{{From: "yard", To: "hall"}, {From: "hall", To: "yard"}}
142		shuffled.Banned = []Edge{{From: "dock", To: "cave"}, {From: "cave", To: "dock"}, {From: "cave", To: "dock"}}
143		fourth := generateWorld(t, shuffled).Snapshot()
144		if !reflect.DeepEqual(first.Rules.Locations, fourth.Rules.Locations) {
145			t.Fatalf("地点输入次序影响结果: %v vs %v", first.Rules.Locations, fourth.Rules.Locations)
146		}
147		if !reflect.DeepEqual(first.Rules.Edges, fourth.Rules.Edges) {
148			t.Fatalf("道路输入次序/重复/正反影响结果: %v vs %v", first.Rules.Edges, fourth.Rules.Edges)
149		}
150	}
