238	func TestGenerateErrors(t *testing.T) {
239		cases := []struct {
240			name string
241			mod  func(*GenerateRequest)
242		}{
243			{"没有地点", func(r *GenerateRequest) { r.Locations = nil }},
244			{"地点过多", func(r *GenerateRequest) {
245				locs := make([]string, 257)
246				for i := range locs {
247					locs[i] = string(rune('a'+i%26)) + string(rune('a'+i/26))
248				}
249				r.Locations = locs
250			}},
251			{"地点标识为空", func(r *GenerateRequest) { r.Locations[0] = "" }},
252			{"地点重复", func(r *GenerateRequest) { r.Locations[1] = r.Locations[0] }},
253			{"必有道路引用未知地点", func(r *GenerateRequest) {
254				r.Required = []Edge{{From: "hall", To: "void"}}
255			}},
256			{"禁用道路引用未知地点", func(r *GenerateRequest) {
257				r.Banned = []Edge{{From: "void", To: "yard"}}
258			}},
259			{"必有道路连接自身", func(r *GenerateRequest) {
260				r.Required = []Edge{{From: "hall", To: "hall"}}
261			}},
262			{"禁用道路连接自身", func(r *GenerateRequest) {
263				r.Banned = []Edge{{From: "cave", To: "cave"}}
264			}},
265			{"同一道路必有且禁用", func(r *GenerateRequest) {
266				r.Banned = []Edge{{From: "yard", To: "hall"}}
267			}},
268			{"目标数量为负", func(r *GenerateRequest) { r.RoadCount = -1 }},
269			{"目标小于必有道路数", func(r *GenerateRequest) {
270				r.Required = []Edge{{From: "hall", To: "yard"}, {From: "cave", To: "dock"}}
271				r.RoadCount = 1
272			}},
273			{"目标少于连通所需", func(r *GenerateRequest) { r.RoadCount = 2 }},
274			{"目标超过可用道路数", func(r *GenerateRequest) {
275				r.Banned = nil
276				r.RoadCount = 7 // 4 个地点最多 6 条
277			}},
278			{"禁用道路使地图无法连通", func(r *GenerateRequest) {
279				r.Required = nil
280				r.Banned = []Edge{
281					{From: "hall", To: "yard"},
282					{From: "hall", To: "cave"},
283					{From: "hall", To: "dock"},
284				}
285			}},
286			{"必有成环抬高连通下限", func(r *GenerateRequest) {
287				// 必有道路在 hall/yard/cave 上成环，连通 dock 至少还需 1 条，
288				// 因此最少需要 4 条；目标 3 条不可行。
289				r.Required = []Edge{
290					{From: "hall", To: "yard"},
291					{From: "yard", To: "cave"},
292					{From: "cave", To: "hall"},
293				}
294				r.RoadCount = 3
295			}},
296			{"规则版本为空", func(r *GenerateRequest) { r.RulesVersion = "" }},
297			{"角色在不存在的地点", func(r *GenerateRequest) {
298				r.Characters = []Character{{ID: "hero", Location: "void"}}
299			}},
300		}
301		for _, tc := range cases {
302			t.Run(tc.name, func(t *testing.T) {
303				req := baseGenerateRequest()
304				tc.mod(&req)
305				if _, err := GenerateWorld(req); err == nil {
306					t.Fatal("期望生成失败，但成功了")
307				} else if _, ok := err.(*RuleError); !ok {
308					t.Fatalf("期望 *RuleError，得到 %T: %v", err, err)
309				}
310			})
311		}
312	}
