327	func TestGenerateInputIsolation(t *testing.T) {
328		req := baseGenerateRequest()
329		w := generateWorld(t, req)
330		before := w.Snapshot()
331	
332		// 生成后修改请求内容不得影响已生成的世界。
333		req.Locations[0] = "mutated"
334		req.Required[0] = Edge{From: "x", To: "y"}
335		req.Banned[0] = Edge{From: "x", To: "y"}
336		req.ItemKinds[0] = "mutated"
337		req.CarryLimits["hero"] = -100
338		req.Characters[0].Location = "mutated"
339		req.Characters[0].Items[0].Count = 99
340		after := w.Snapshot()
341		if !reflect.DeepEqual(before, after) {
342			t.Fatal("修改请求输入影响到了已生成的世界")
343		}
344	
345		// 修改快照不得影响世界；另一次生成不得影响此前结果。
346		snap := w.Snapshot()
347		snap.Rules.Edges[0] = Edge{From: "a", To: "b"}
348		other := baseGenerateRequest()
349		other.Seed = 7
350		_ = generateWorld(t, other)
351		if !reflect.DeepEqual(before, w.Snapshot()) {
352			t.Fatal("修改快照或另一次生成影响到了此前的世界")
353		}
354	}
