368	func TestGeneratedWorldApplyAndArchive(t *testing.T) {
369		req := baseGenerateRequest()
370		w := generateWorld(t, req)
371		st := w.Snapshot()
372	
373		// 沿生成的道路移动。
374		e := st.Rules.Edges[0]
375		hero := st.Characters[0]
376		from, to := e.From, e.To
377		if hero.Location == to {
378			from, to = to, from
379		}
380		// 先把 hero 放到道路一端（直接重建世界，避免多步移动）。
381		req.Characters = []Character{{ID: "hero", Location: from, Items: []CharacterItem{{Item: "gold", Count: 1}}}}
382		w = generateWorld(t, req)
383		if _, err := w.Apply(Commit{Moves: []Move{{Character: "hero", To: to}}, Time: 1}); err != nil {
384			t.Fatalf("沿生成道路移动失败: %v", err)
385		}
386	
387		// 存档后重新打开，地图来自记录而不是重新生成。
388		dir := t.TempDir()
389		a, err := Create(dir)
390		if err != nil {
391			t.Fatalf("Create: %v", err)
392		}
393		info, err := a.Save("slot", w)
394		if err != nil {
395			t.Fatalf("Save: %v", err)
396		}
397		a2, err := Open(dir)
398		if err != nil {
399			t.Fatalf("Open: %v", err)
400		}
401		rec, err := a2.Record("slot", info.ID, []string{"v1"})
402		if err != nil {
403			t.Fatalf("Record: %v", err)
404		}
405		if !reflect.DeepEqual(st.Rules.Locations, rec.State.Rules.Locations) ||
406			!reflect.DeepEqual(w.Snapshot().Rules.Edges, rec.State.Rules.Edges) {
407			t.Fatal("重新打开后地图与记录不符")
408		}
409		// 读档重建的世界仍可按这些道路移动（沿同一条道路返回）。
410		w2, err := WorldFromState(rec.State)
411		if err != nil {
412			t.Fatalf("WorldFromState: %v", err)
413		}
414		if _, err := w2.Apply(Commit{Moves: []Move{{Character: "hero", To: from}}, Time: 2}); err != nil {
415			t.Fatalf("读档后沿道路移动失败: %v", err)
416		}
417	}
