package world

import (
	"math/rand"
	"reflect"
	"testing"
)

// 暴力枚举小规模约束，核对：有解时各种子都成功且地图合法；无解时失败。
func TestExhaustiveFeasibility(t *testing.T) {
	seeds := []int64{0, 1, 2, 3, 7, -1, -42, 1 << 40, -(1 << 40)}
	for n := 2; n <= 5; n++ {
		locs := make([]string, n)
		for i := range locs {
			locs[i] = string(rune('a' + i))
		}
		var all []Edge
		for i := 0; i < n; i++ {
			for j := i + 1; j < n; j++ {
				all = append(all, Edge{From: locs[i], To: locs[j]})
			}
		}
		m := len(all)
		// 枚举禁用集合与必有集合（互不相交）。
		for banMask := 0; banMask < (1 << m); banMask++ {
			for reqMask := 0; reqMask < (1 << m); reqMask++ {
				if reqMask&banMask != 0 {
					continue
				}
				var required, banned []Edge
				for k, e := range all {
					if banMask>>k&1 == 1 {
						banned = append(banned, e)
					}
					if reqMask>>k&1 == 1 {
						required = append(required, e)
					}
				}
				// 可行性预言：必有道路分量数 c，候选（未禁用）图连通，
				// 且 |R|+c-1 <= roadCount <= 候选边数。
				uf := newUnionFind(n)
				comp := n
				for _, e := range required {
					if uf.union(int(e.From[0]-'a'), int(e.To[0]-'a')) {
						comp--
					}
				}
				cf := newUnionFind(n)
				cand := 0
				for _, e := range all {
					if !containsE(banned, e) {
						cand++
						cf.union(int(e.From[0]-'a'), int(e.To[0]-'a'))
					}
				}
				candConnected := true
				for i := 1; i < n; i++ {
					if cf.find(i) != cf.find(0) {
						candConnected = false
					}
				}
				for rc := 0; rc <= m; rc++ {
					solvable := candConnected && rc >= len(required)+comp-1 && rc <= cand
					var ref []Edge
					for _, s := range seeds {
						req := GenerateRequest{
							Seed: s, Locations: locs, Required: required,
							Banned: banned, RoadCount: rc, RulesVersion: "v1",
						}
						w, err := GenerateWorld(req)
						if solvable {
							if err != nil {
								t.Fatalf("n=%d req=%v ban=%v rc=%d seed=%d: 有解却失败: %v",
									n, required, banned, rc, s, err)
							}
							edges := w.Snapshot().Rules.Edges
							validateMap(t, locs, required, banned, rc, edges)
							if ref == nil {
								ref = append([]Edge(nil), edges...)
							} else if s == seeds[0] {
								// 占位
							}
						} else {
							if err != nil {
								if _, ok := err.(*RuleError); !ok {
									t.Fatalf("n=%d rc=%d: 期望 *RuleError，得到 %T", n, rc, err)
								}
							} else {
								t.Fatalf("n=%d req=%v ban=%v rc=%d: 无解却成功: %v",
									n, required, banned, rc, w.Snapshot().Rules.Edges)
							}
						}
					}
				}
			}
		}
	}
}

func containsE(es []Edge, e Edge) bool {
	for _, x := range es {
		if x == e {
			return true
		}
	}
	return false
}

func validateMap(t *testing.T, locs []string, required, banned []Edge, rc int, edges []Edge) {
	t.Helper()
	if len(edges) != rc {
		t.Fatalf("道路数量应为 %d，得到 %d: %v", rc, len(edges), edges)
	}
	seen := map[Edge]bool{}
	for _, e := range edges {
		if e.From >= e.To {
			t.Fatalf("方向不规范: %v", edges)
		}
		if seen[e] {
			t.Fatalf("重复道路: %v", edges)
		}
		seen[e] = true
	}
	for _, r := range required {
		if !seen[canonicalEdge(r)] {
			t.Fatalf("缺必有道路 %v: %v", r, edges)
		}
	}
	for _, b := range banned {
		if seen[canonicalEdge(b)] {
			t.Fatalf("含禁用道路 %v: %v", b, edges)
		}
	}
	n := len(locs)
	idx := map[string]int{}
	for i, l := range locs {
		idx[l] = i
	}
	uf := newUnionFind(n)
	for _, e := range edges {
		uf.union(idx[e.From], idx[e.To])
	}
	for i := 1; i < n; i++ {
		if uf.find(i) != uf.find(0) {
			t.Fatalf("地图不连通: %v", edges)
		}
	}
}

// 输入次序、重复、反写不影响结果。
func TestExhaustiveInputOrderInvariance(t *testing.T) {
	rng := rand.New(rand.NewSource(1))
	for iter := 0; iter < 300; iter++ {
		n := 2 + rng.Intn(6)
		locs := make([]string, n)
		for i := range locs {
			locs[i] = string(rune('a' + i))
		}
		var all []Edge
		for i := 0; i < n; i++ {
			for j := i + 1; j < n; j++ {
				all = append(all, Edge{From: locs[i], To: locs[j]})
			}
		}
		var req, ban []Edge
		for _, e := range all {
			r := rng.Intn(3)
			if r == 0 {
				req = append(req, e)
			} else if r == 1 {
				ban = append(ban, e)
			}
		}
		cand := len(all) - len(ban)
		comp := n
		uf := newUnionFind(n)
		for _, e := range req {
			if uf.union(int(e.From[0]-'a'), int(e.To[0]-'a')) {
				comp--
			}
		}
		cf := newUnionFind(n)
		for _, e := range all {
			if !containsE(ban, e) {
				cf.union(int(e.From[0]-'a'), int(e.To[0]-'a'))
			}
		}
		connected := true
		for i := 1; i < n; i++ {
			if cf.find(i) != cf.find(0) {
				connected = false
			}
		}
		if !connected {
			continue
		}
		minR := len(req) + comp - 1
		if minR > cand {
			continue
		}
		rc := minR + rng.Intn(cand-minR+1)
		seed := int64(rng.Intn(200) - 100)

		base := GenerateRequest{Seed: seed, Locations: locs, Required: req, Banned: ban, RoadCount: rc, RulesVersion: "v1"}
		w1, err := GenerateWorld(base)
		if err != nil {
			t.Fatalf("iter=%d 意外失败: %v", iter, err)
		}
		// 打乱地点次序、反写并重复道路。
		locs2 := append([]string(nil), locs...)
		rng.Shuffle(len(locs2), func(i, j int) { locs2[i], locs2[j] = locs2[j], locs2[i] })
		mess := func(es []Edge) []Edge {
			var out []Edge
			for _, e := range es {
				out = append(out, e)
				if rng.Intn(2) == 0 {
					out = append(out, Edge{From: e.To, To: e.From})
				}
				if rng.Intn(3) == 0 {
					out = append(out, e)
				}
			}
			rng.Shuffle(len(out), func(i, j int) { out[i], out[j] = out[j], out[i] })
			return out
		}
		mod := GenerateRequest{
			Seed: seed, Locations: locs2, Required: mess(req), Banned: mess(ban),
			RoadCount: rc, RulesVersion: "v9", // 规则版本不参与选图
		}
		w2, err := GenerateWorld(mod)
		if err != nil {
			t.Fatalf("iter=%d 等价输入失败: %v", iter, err)
		}
		if !reflect.DeepEqual(w1.Snapshot().Rules.Locations, w2.Snapshot().Rules.Locations) ||
			!reflect.DeepEqual(w1.Snapshot().Rules.Edges, w2.Snapshot().Rules.Edges) {
			t.Fatalf("iter=%d seed=%d 等价输入地图不一致:\n%v\n%v", iter, seed,
				w1.Snapshot().Rules.Edges, w2.Snapshot().Rules.Edges)
		}
	}
}
