package world

import (
	"reflect"
	"testing"
)

func allEdges(locs []string) []Edge {
	var es []Edge
	for i := 0; i < len(locs); i++ {
		for j := i + 1; j < len(locs); j++ {
			es = append(es, Edge{From: locs[i], To: locs[j]})
		}
	}
	return es
}

func TestTaskExamples(t *testing.T) {
	locs := []string{"a", "b", "c", "d"}
	want6 := allEdges(locs)

	// 四地点、无必有无禁用、目标六条：任意种子都应得到全部六条。
	for s := int64(-100); s <= 100; s++ {
		w, err := GenerateWorld(GenerateRequest{Seed: s, Locations: locs, RoadCount: 6, RulesVersion: "v1"})
		if err != nil {
			t.Fatalf("seed=%d 目标6条失败: %v", s, err)
		}
		if got := w.Snapshot().Rules.Edges; !reflect.DeepEqual(got, want6) {
			t.Fatalf("seed=%d 地图不是全部六条: %v", s, got)
		}
	}

	// 禁用 c-d，目标五条：恰好其余五条。
	want5 := []Edge{{From: "a", To: "b"}, {From: "a", To: "c"}, {From: "a", To: "d"},
		{From: "b", To: "c"}, {From: "b", To: "d"}}
	for s := int64(-100); s <= 100; s++ {
		w, err := GenerateWorld(GenerateRequest{
			Seed: s, Locations: locs, RoadCount: 5, RulesVersion: "v1",
			Banned: []Edge{{From: "d", To: "c"}}, // 反写
		})
		if err != nil {
			t.Fatalf("seed=%d 目标5条失败: %v", s, err)
		}
		if got := w.Snapshot().Rules.Edges; !reflect.DeepEqual(got, want5) {
			t.Fatalf("seed=%d 地图不是其余五条: %v", s, got)
		}
	}

	// 必有三条边成环（a-b-c），目标 4：必须连上 d，且保留三条必有边。
	for s := int64(-100); s <= 100; s++ {
		w, err := GenerateWorld(GenerateRequest{
			Seed: s, Locations: locs, RoadCount: 4, RulesVersion: "v1",
			Required: []Edge{{"a", "b"}, {"b", "c"}, {"c", "a"}},
		})
		if err != nil {
			t.Fatalf("seed=%d 成环+目标4失败: %v", s, err)
		}
		validateMap(t, locs,
			[]Edge{{"a", "b"}, {"b", "c"}, {"c", "a"}}, nil, 4, w.Snapshot().Rules.Edges)
	}

	// 成环但目标 3：无法连接 d，必须失败。
