	for i := range big {
		big[i] = string(rune('a' + i))
	}
	ban := []Edge{{"a", "b"}, {"c", "d"}, {"e", "f"}, {"g", "h"}}
	cand := n*(n-1)/2 - len(ban)
	for s := int64(0); s < 50; s++ {
		for rc := n - 1; rc <= cand; rc++ {
			w, err := GenerateWorld(GenerateRequest{
				Seed: s, Locations: big, Banned: ban, RoadCount: rc, RulesVersion: "v1",
			})
